-- Nativo: categorias nos Modelos do Nativo + 19 modelos novos (referências
-- enviadas pelo Junior em 26/09). A categoria fica em doc->>'category' (sem
-- coluna nova); a tela inicial agrupa os modelos por ela.
-- Idempotente: não duplica modelo com o mesmo nome.

UPDATE public.nativo_projects SET doc = jsonb_set(doc, '{category}', '"Aesthetic"')
WHERE kind = 'official' AND name IN ('Manchete espalhada', 'Capa editorial', 'Mistura de estilos', 'Frase com estrelas', 'Carrossel frase quebrada', 'Balão do iMessage', 'Caixa de mensagem') AND doc->>'category' IS NULL;

